<template><view class="page"><view class="card"><view class="row"><text>身高(cm)</text><input v-model="form.heightCm" type="digit"/></view><view class="row"><text>体重(kg)</text><input v-model="form.weightKg" type="digit"/></view><view class="row"><text>糖尿病类型</text><input v-model="form.diabetesType" placeholder="选填"/></view><view class="row"><text>目标血糖下限</text><input v-model="form.glucoseTargetMin" type="digit"/></view><view class="row"><text>目标血糖上限</text><input v-model="form.glucoseTargetMax" type="digit"/></view><view class="row"><text>健康备注</text><input v-model="form.remark" placeholder="敏感字段将按配置加密"/></view></view><button @tap="save">保存档案</button></view></template><script>import{getHealthProfile,saveHealthProfile}from'@/api/health.js';export default{data(){return{form:{}}},onShow(){getHealthProfile().then(r=>this.form=(r&&r.data)||r||{})},methods:{save(){saveHealthProfile(this.form).then(()=>uni.showToast({title:'保存成功'}))}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.card{background:#fff;border-radius:20rpx;padding:0 24rpx}.row{display:flex;justify-content:space-between;align-items:center;min-height:92rpx;border-bottom:1rpx solid #eee}.row input{text-align:right;flex:1;margin-left:20rpx}.page>button{margin-top:28rpx;background:#19bf9b;color:#fff}</style>